/* =====================================================================
   US-DATA.JS — the United States outline for the national-parks map
   ---------------------------------------------------------------------
   Generated once from us-atlas (Census 1:10m state boundaries) and
   projected here, not at runtime, with a composite Albers equal-area:

     lower 48   Albers conic, standard parallels 29.5N / 45.5N, on -96
     Alaska     its own Albers (55N / 65N, on -154), drawn at 0.35 scale
     Hawaii     its own Albers (8N / 18N, on -157), full scale

   Alaska and Hawaii are laid out in a strip down the west side, roughly
   where they sit in the world, so nothing overlaps the lower 48.

   US_PROJECT(lat, lon) below repeats exactly the same maths for the park
   pins, so a pin and the coastline always agree. Keep the two in step: if
   you change a constant here you have to re-generate the paths.
   ===================================================================== */
const US_MAP = {"view":{"x":0,"y":0,"w":1000,"h":500.4},"kmPerUnit":6.3909,"scale":1007.640508,"tx":624.0374,"ty":267.8439,"regions":{"us":{"n":0.6028370046288244,"C":1.351221325417899,"rho0":1.3032624269880215,"lam0":-96,"k":1.0,"ox":0.0,"oy":0.0},"ak":{"n":0.8627299156628209,"C":1.742403876506104,"rho0":0.751748660421638,"lam0":-154,"k":0.35,"ox":-0.4806044616207011,"oy":-0.11563024848123465},"hi":{"n":0.22409504766750643,"C":1.0430068533565207,"rho0":4.2091426031964785,"lam0":-157,"k":1.0,"ox":-0.5262080494857947,"oy":0.1820157701653593}}};

/* lat/lon -> a point in the US_MAP.view grid */
function US_PROJECT(lat, lon) {
  if (lon > 0) lon -= 360;                       // the Aleutians, past the date line
  var g = (lat > 50 && lon < -125) ? 'ak' : (lat < 25 && lon < -150) ? 'hi' : 'us';
  var r = US_MAP.regions[g], D = Math.PI / 180;
  var t = r.n * ((lon - r.lam0) * D);
  var rr = Math.sqrt(Math.max(0, r.C - 2 * r.n * Math.sin(lat * D))) / r.n;
  return {
    x: ((rr * Math.sin(t)) * r.k + r.ox) * US_MAP.scale + US_MAP.tx,
    y: ((rr * Math.cos(t) - r.rho0) * r.k + r.oy) * US_MAP.scale + US_MAP.ty
  };
}

